# HatzLocalConsoleV7-1.ps1
# Generated: 2026-07-17
# Forensic analyst system prompts upgrade

$ErrorActionPreference = "Stop"

# --- Configuration ---
$Port = 8080
$BrowserAutoLaunch = $true

# --- Embedded HTML (base64-encoded) ---
$HtmlB64 = @'

'@

$Html = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($HtmlB64))

# --- HTTP listener ---
$Listener = New-Object System.Net.HttpListener
$Listener.Prefixes.Add("http://localhost:$Port/")
$Listener.Start()
Write-Host "Hatz Local Console running at http://localhost:$Port" -ForegroundColor Green
Write-Host "Press Ctrl+C to stop." -ForegroundColor Yellow
if ($BrowserAutoLaunch) { Start-Process "http://localhost:$Port" }

try {
    while ($Listener.IsListening) {
        $Context = $Listener.GetContext()
        $Response = $Context.Response
        $Bytes = [System.Text.Encoding]::UTF8.GetBytes($Html)
        $Response.ContentType = "text/html; charset=utf-8"
        $Response.ContentLength64 = $Bytes.Length
        $Response.OutputStream.Write($Bytes, 0, $Bytes.Length)
        $Response.OutputStream.Close()
    }
} finally {
    $Listener.Stop()
}
